/// <summary>
/// designed by AVANADE
/// </summary>
[ExtensionOf(tableStr(PriceDiscAdmTrans))]
final class AVAPriceDiscAdmTransDbt_Extension
{
}

Method.Source:
/// <summary>
/// designed by AVANADE
/// </summary>
public void initValue()
{
    next initValue();
    this.SearchAgain = NoYes::No;
    this.initInventTableFields();
}

/// <summary>
///     AVA <c>initInventTableFields</c> method.
/// </summary>
private void initInventTableFields()
{
    InventTable inventTable;
    if (this.itemId())
    {
        inventTable = inventTable::find(this.itemId());
        this.KCS_KAOItemState   = InventTable.KCS_KAOItemState;
        this.KCS_GoodsId        = inventTable.KCS_GoodsId;

        if(this.relation == PriceType::PriceSales)
        {
            this.PriceUnit = inventTable.inventTableModuleSales().PriceUnit;
        }
        else if(this.relation == PriceType::PricePurch)
        {
            this.PriceUnit = inventTable.inventTableModulePurch().PriceUnit;
        }
    }
}

/// <summary>
/// designed by AVANADE
/// </summary>
public void initFromItemCode()
{
    InventTable     inventTable;

    next initFromItemCode();
    if (this.itemId())
    {
        inventTable = InventTable::find(this.itemId());
        this.KCS_KAOItemState   = InventTable.KCS_KAOItemState;
        this.KCS_GoodsId        = inventTable.KCS_GoodsId;

        if(this.relation == PriceType::PriceSales)
        {
            this.PriceUnit = inventTable.inventTableModuleSales().PriceUnit;
        }
        else if(this.relation == PriceType::PricePurch)
        {
            this.PriceUnit = inventTable.inventTableModulePurch().PriceUnit;
        }
    }
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_priceDiscTable">PriceDiscTable</param>
public void initFromPriceDiscTable(PriceDiscTable _priceDiscTable)
{
    next initFromPriceDiscTable(_priceDiscTable);
    this.KCS_AmountOld                 = _priceDiscTable.Amount;
    this.AVAGraduatedPrice             = _priceDiscTable.AVAGraduatedPrice;
    this.AVAOldCurrency                = _priceDiscTable.Currency;
    this.AVAOldFromDate                = _priceDiscTable.FromDate;
    this.AVAOldToDate                  = _priceDiscTable.ToDate;
    this.AVAEffectivePrice             = _priceDiscTable.AVAEffectivePrice;
    this.initInventTableFields();
}

/// <summary>
///     AVA <c>initFactorFields</c> method.
/// </summary>
private void initFactorFields()
{
    Price hk2;

    hk2 = InventTable::find(this.itemId()).AVAGetHK2perQty(1,this.InventDimId, this.ToDate ? this.ToDate : DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
    this.KCS_FactorOldToNewAmount   = this.KCS_AmountOld    ? this.Amount/this.KCS_AmountOld    : 0;
    this.KCS_FactorNewAmountToHK2   = hk2                   ? this.Amount/hk2                   : 0;
    if (this.PriceUnit)
    {
        this.KCS_FactorNewAmountToHK2 = this.KCS_FactorNewAmountToHK2 / this.PriceUnit;    
    }
}

/// <summary>
///     AVA <c>update</c> method.
/// </summary>
public void  update()
{
    this.initFactorFields();
    this.initInventTableFields();
    next update();
}

/// <summary>
///     AVA <c>insert</c> method.
/// </summary>
public void  insert()
{
    this.initFactorFields();
    this.initInventTableFields();
    next insert();
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    //Price hk2;

    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldnum(PriceDiscAdmTrans,Amount):
            this.initFactorFields();
            break;

        case fieldnum(PriceDiscAdmTrans,KCS_AmountOld):
            this.KCS_FactorOldToNewAmount   = this.KCS_AmountOld    ? this.Amount/this.KCS_AmountOld    : 0;
            break;

    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_jourNum">_jourNum</param>
/// <returns>boolean</returns>
public static boolean hasNewAndClosePos(PriceDiscJournalNum _jourNum)
{
    PriceDiscAdmTrans locpdAdmTrans;

    select firstonly locpdAdmTrans where locpdAdmTrans.JournalNum == _jourNum
        && locpdAdmTrans.KCS_NewAndClose;
    return locpdAdmTrans.RecId;
}
